<template>
<section class="whois-tool" aria-labelledby="whois-title"><h3 id="whois-title">WHOIS / RDAP 信息查询</h3><p>查询域名或 IP 的公开登记信息。点击查询后会将查询对象发送至 RDAP 引导服务及相应登记机构，不查询个人住址。</p><form @submit.prevent="query"><label for="whois-input">域名或 IP 地址</label><div class="whois-input-row"><input id="whois-input" v-model="input" type="text" maxlength="2048" spellcheck="false" autocomplete="off" placeholder="example.com / 1.1.1.1 / 2001:db8::1" /><button type="submit" :disabled="loading||!input.trim()">{{loading?'查询中…':'查询登记信息'}}</button><button type="button" @click="clear">清空</button></div></form><p v-if="error" role="alert" class="whois-error">{{error}}</p><div v-if="rows.length" class="whois-results"><dl><template v-for="(row,index) in rows" :key="index"><dt>{{row[0]}}</dt><dd>{{row[1]}}</dd></template></dl><details><summary>查看原始 RDAP JSON</summary><pre>{{raw}}</pre></details></div><p v-if="lookup" class="whois-links"><a :href="endpoint" target="_blank" rel="noopener noreferrer">打开 RDAP 登记信息原文 ↗</a><a v-if="lookup.type==='domain'" :href="`https://lookup.icann.org/en/lookup?name=${encodeURIComponent(lookup.value)}`" target="_blank" rel="noopener noreferrer">ICANN 查询入口 ↗</a></p><small>WHOIS 的结构化查询使用 RDAP。部分后缀未支持、跨域限制、网络或频率限制会导致查询失败；“未公开”不等于不存在。IP 登记地区不等于设备实际位置。</small></section>
</template>
<script>
import {normalizeWhoisInput,summarizeRdap} from '../utils/whois-query.mjs';
export default{name:'WhoisQuery',data:()=>({input:'',lookup:null,rows:[],raw:'',error:'',loading:false,controller:null,request:0}),computed:{endpoint(){return this.lookup?`https://rdap.org/${this.lookup.type}/${encodeURIComponent(this.lookup.value)}`:'';}},beforeUnmount(){this.request++;this.controller?.abort();},methods:{clear(){this.request++;this.controller?.abort();this.input='';this.lookup=null;this.rows=[];this.raw='';this.error='';this.loading=false;},async query(){this.controller?.abort();const request=++this.request;this.error='';this.rows=[];this.raw='';try{this.lookup=normalizeWhoisInput(this.input);}catch(e){this.lookup=null;this.error=e.message;return;}this.loading=true;this.controller=new AbortController();const timeout=setTimeout(()=>this.controller.abort(),15000);try{const response=await fetch(this.endpoint,{signal:this.controller.signal,credentials:'omit',headers:{Accept:'application/rdap+json, application/json'}});if(!response.ok)throw Error(response.status===404?'未找到此对象的登记信息或可用 RDAP 服务':response.status===429?'查询过于频繁，请稍后重试':`登记服务返回 HTTP ${response.status}`);const data=await response.json();if(request!==this.request)return;this.rows=summarizeRdap(data);this.raw=JSON.stringify(data,null,2);}catch(e){if(request===this.request)this.error=e.name==='AbortError'?'查询超时，请重试或打开下方原文入口。':`查询未完成：${e.message}。可通过下方入口查看。`;}finally{clearTimeout(timeout);if(request===this.request)this.loading=false;}}}};
</script>
<style scoped>
.whois-tool{margin-top:16px}.whois-tool h3{font-size:15px}.whois-tool p,.whois-tool small{font-size:12px;line-height:1.8;color:var(--el-text-color-secondary)}label{display:block;font-size:12px;margin:12px 0 8px}.whois-input-row{display:flex;gap:8px;flex-wrap:wrap}input,button{font:inherit;font-size:12px;padding:9px 11px;border:1px solid var(--el-border-color);border-radius:6px;background:var(--el-fill-color-blank);color:var(--el-text-color-primary);box-sizing:border-box}input{min-width:0;flex:1 1 240px}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}button:focus-visible,input:focus-visible{outline:2px solid var(--ui-accent);outline-offset:2px}.whois-tool .whois-error{color:var(--el-color-danger,#c95757)}dl{display:grid;grid-template-columns:130px minmax(0,1fr);border:1px solid var(--el-border-color-light);border-radius:8px;overflow:hidden;margin-top:16px}dt,dd{margin:0;padding:10px;border-bottom:1px solid var(--el-border-color-light);font-size:12px;line-height:1.7;overflow-wrap:anywhere;white-space:pre-wrap}dt{background:var(--ui-accent-soft)}pre{max-height:300px;overflow:auto;font-size:11px;line-height:1.7;white-space:pre-wrap;overflow-wrap:anywhere}.whois-links{display:flex;gap:14px;flex-wrap:wrap}a{color:var(--ui-accent)}summary{font-size:12px;cursor:pointer}@media(max-width:600px){dl{grid-template-columns:95px minmax(0,1fr)}}
</style>
